### File type classifier rejects .sql files

Source: https://github.com/kysely-org/kysely-ctl/blob/main/src/utils/get-file-type.mts

The getFileType function only recognizes .ts/.mts/.cts (TS) and .js/.mjs/.cjs (JS). Any other extension, including .sql, returns 'IRRELEVANT'. This means .sql files are never considered as migration candidates.

```typescript
export function getFileType(path: string): 'TS' | 'JS' | 'IRRELEVANT' {
	let extension = ''
	const lastIndex = path.length - 1
	let i = 0

	for (; i < 3; i++) {
		const char = path.charAt(lastIndex - i)

		if (char === '.') {
			break
		}

		extension = `${char}${extension}`
	}

	if (
		extension.length < 2 ||
		path.charAt(lastIndex - i) !== '.' ||
		(path.charAt(lastIndex - (i + 1)) === 'd' &&
			path.charAt(lastIndex - (i + 2)) === '.')
	) {
		return 'IRRELEVANT'
	}

	if (['ts', 'mts', 'cts'].includes(extension)) {
		return 'TS'
	}

	if (['js', 'mjs', 'cjs'].includes(extension)) {
		return 'JS'
	}

	return 'IRRELEVANT'
}
```

